import { Box, IconButton, Tooltip } from '@mui/material'
import Fullscreen from 'mdi-material-ui/Fullscreen'
import FullscreenExit from 'mdi-material-ui/FullscreenExit'
import type { CardTypeConfig } from '../../data/data_types'
import type { CardMarkdownDataSource } from '../editor/card_markdown_data_source'
import { MarkdownFormatToolbarControls } from '../editor/markdown_format_toolbar_controls'
import { CardPropertiesControl } from '../text_view/card_properties_control'

interface CardPopupToolbarControlsProps {
    cardTypes: CardTypeConfig[]
    dataSource: CardMarkdownDataSource
    isFullscreen: boolean
    isMobile: boolean
    onToggleFullscreen: () => void
    readOnly: boolean
    statusColors: Map<string, string>
}

/** Formatting controls arranged for the card details popup. */
export function CardPopupToolbarControls(props: CardPopupToolbarControlsProps) {
    const { cardTypes, dataSource, isFullscreen, isMobile, onToggleFullscreen, readOnly, statusColors } = props
    const label = isFullscreen ? 'Exit fullscreen' : 'Fullscreen'

    return (
        <MarkdownFormatToolbarControls endControls={(
            <>
                <Box sx={{ flex: 1 }} />
                {!readOnly ? <CardPropertiesControl binding="board-card" cardTypes={cardTypes} dataSource={dataSource} statusColors={statusColors} /> : null}
                {!isMobile ? (
                    <Tooltip title={label}>
                        <IconButton aria-label={label} onClick={onToggleFullscreen} size="small" sx={{ height: 30, width: 30 }}>
                            {isFullscreen ? <FullscreenExit sx={{ fontSize: 17 }} /> : <Fullscreen sx={{ fontSize: 17 }} />}
                        </IconButton>
                    </Tooltip>
                ) : null}
            </>
        )} readOnly={readOnly} />
    )
}

import { MenuItem } from '@mui/material'
import { dialogService } from '../../services/dialog_service'

interface CardPathMenuItemsProps {
    cardPath: string
    onSelected: () => void
    rootPath?: string
}

function absoluteCardPath(rootPath: string, cardPath: string) {
    const separator = rootPath.includes('\\') ? '\\' : '/'
    const normalizedRootPath = rootPath.replace(/[\\/]+$/gu, '')
    const normalizedCardPath = cardPath.replace(/[\\/]/gu, separator).replace(/^[\\/]+/gu, '')

    return `${normalizedRootPath}${separator}${normalizedCardPath}`
}

async function copyCardPath(path: string, onSelected: () => void) {
    onSelected()
    try {
        await navigator.clipboard.writeText(path)
    } catch (error) {
        dialogService.error(error, { fallbackMessage: 'Path could not be copied to clipboard' })
    }
}

/** Shared path-copy commands for menus representing parsed cards. */
export function CardPathMenuItems(props: CardPathMenuItemsProps) {
    const { cardPath, onSelected, rootPath } = props

    const copyAbsolutePath = () => {
        if (!rootPath) throw new Error('Cannot copy absolute card path without project root path')
        void copyCardPath(absoluteCardPath(rootPath, cardPath), onSelected)
    }

    const copyRelativePath = () => {
        void copyCardPath(cardPath, onSelected)
    }

    return (
        <>
            {rootPath ? <MenuItem onClick={copyAbsolutePath}>Copy path</MenuItem> : null}
            <MenuItem onClick={copyRelativePath}>Copy relative path</MenuItem>
        </>
    )
}
